#include <stdio.h>

/**
 * Swaps two integers pointed to by a and b.
 */
void swap(int *a, int *b) {
    int temp = *a;
    *a = *b;
    *b = temp;
}

/**
 * Partitions the array around a pivot element.
 * Uses the last element as the pivot.
 * Elements less than or equal to the pivot are moved to the left,
 * and elements greater than the pivot are moved to the right.
 * Returns the final index of the pivot element.
 */
int partition(int arr[], int low, int high) {
    int pivot = arr[high];  // Choose the last element as pivot
    int i = (low - 1);      // Index of the smaller element (initially before the start)

    for (int j = low; j < high; j++) {
        // If current element is smaller than or equal to pivot
        if (arr[j] <= pivot) {
            i++;            // Increment index of smaller element
            swap(&arr[i], &arr[j]);  // Move current element to the left partition
        }
    }
    // Place the pivot in its correct position
    swap(&arr[i + 1], &arr[high]);
    return (i + 1);  // Return the pivot index
}

/**
 * Recursive quicksort function.
 * Sorts the array in-place between indices low and high.
 */
void quicksort(int arr[], int low, int high) {
    if (low < high) {
        // pi is the partitioning index; arr[pi] is now in the correct position
        int pi = partition(arr, low, high);

        // Recursively sort elements before and after partition
        quicksort(arr, low, pi - 1);   // Sort left half
        quicksort(arr, pi + 1, high);  // Sort right half
    }
}

